<template>
  <div class="activity-logs left-scroll-area-height">
    <div class="logs-scroll-area">
      <q-list class="full-width">
        <q-item v-for="log in logs" :key="log.id" class="q-my-sm">
          <q-item-section avatar>
            <q-avatar color="primary" text-color="white">
              {{ log.avatar_letters }}
            </q-avatar>
          </q-item-section>

          <q-item-section>
            <q-item-label caption lines="1">
              {{ formatLogTime(log.created_on) }} {{ $t('by') }}
              {{ log.created_by_name }}
            </q-item-label>
            <q-item-label>
              <span v-html="renderMentions(log.action_description)"></span>
            </q-item-label>
          </q-item-section>
        </q-item>
      </q-list>
    </div>

    <q-list class="full-width composer-area">
      <q-item>
        <q-item-section>
          <div class="mention-input-wrapper">
            <div class="comment-editor-container" :class="{ 'comment-editor-error': new_message['error'] }">
              <div
                ref="commentEditor"
                class="comment-editor"
                contenteditable="true"
                @input="onEditorInput"
                @keydown="onInputKeydown"
                @focus="editorFocused = true"
                @blur="editorFocused = false"
              ></div>
              <span
                v-if="!new_message['text'] && !editorFocused"
                class="comment-placeholder"
                @click="focusEditor"
              >
                {{ $t('write_comment') }}
              </span>
              <div class="comment-editor-actions">
                <q-icon
                  v-if="new_message['error']"
                  flat
                  dense
                  name="error"
                  size="24px"
                  color="red"
                >
                  <q-tooltip class="bg-red line-error-tooltip">
                    Commnet required
                  </q-tooltip>
                </q-icon>

                <q-icon
                  flat
                  dense
                  size="36px"
                  color="primary"
                  class="cursor-pointer"
                  @click="postComment"
                >
                  <Icon icon="mdi:send" width="36" height="36" />
                </q-icon>
              </div>
            </div>

            <q-menu
              ref="mentionMenu"
              v-model="showMentionList"
              no-parent-event
              :target="mentionMenuTarget"
              anchor="top left"
              self="bottom left"
              no-focus
              no-refocus
              :offset="[0, 4]"
            >
              <q-list ref="mentionDropdownList" dense class="mention-dropdown">
                <q-item
                  v-for="(user, index) in filteredUsers"
                  :key="user.id"
                  clickable
                  v-close-popup
                  :active="index === mentionActiveIndex"
                  active-class="bg-primary text-white"
                  @click="selectMention(user)"
                >
                  <q-item-section avatar class="mention-avatar-section">
                    <q-avatar size="24px" color="primary" text-color="white" class="text-caption">
                      {{ getAvatarLetters(getUserFullName(user)) }}
                    </q-avatar>
                  </q-item-section>
                  <q-item-section>
                    <q-item-label>{{ getUserFullName(user) }}</q-item-label>
                    <q-item-label caption>{{ user.email }}</q-item-label>
                  </q-item-section>
                </q-item>
                <q-item v-if="filteredUsers.length === 0">
                  <q-item-section>
                    <q-item-label class="text-muted-foreground">
                      {{ $t('no_results') || 'No users found' }}
                    </q-item-label>
                  </q-item-section>
                </q-item>
              </q-list>
            </q-menu>
          </div>
        </q-item-section>
      </q-item>
    </q-list>

    <q-inner-loading :showing="loading">
      <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
    </q-inner-loading>
  </div>
</template>

<script lang="ts">

import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import helperMixin from 'src/mixins/helperMixin.js';
import { ApiExceptions } from 'src/exceptions/index';
import { useFormattedTimeAgo } from 'src/boot/timeago';
import { documentDetailApiService } from 'src/services';
import { notify } from 'src/components/notifications/notify';
import { getUserDetailFromkey } from 'src/utils/UserDetails';
import { useDocumentStore, useUserStore } from 'src/store/main';

export interface MentionedUser {
  name: string;
  user_id: number | string;
  email: string;
}

function escapeHtml(text: string): string {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function escapeRegex(str: string): string {
  return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

export default defineComponent({
  mixins: [helperMixin],
  props: {
    docId: {
      type: String,
      default: '',
    },
  },

  setup() {
    const doc_store = useDocumentStore();
    const { doc_status } = storeToRefs(doc_store);

    const user_store = useUserStore();
    const { getAllUsers } = user_store;
    const { allUsers } = storeToRefs(user_store);

    return {
      loading: ref(false),
      doc_status,
      logs: ref([] as any),
      new_message: ref({ error: false, text: '' }),
      getAllUsers,
      allUsers,
      showMentionList: ref(false),
      mentionSearch: ref(''),
      mentionStartIndex: ref(-1),
      mentionActiveIndex: ref(0),
      mentionMenuTarget: ref(false as any),
      mentionedUsers: ref([] as MentionedUser[]),
      editorFocused: ref(false),
    };
  },

  computed: {
    filteredUsers(): any[] {
      if (!this.allUsers || !Array.isArray(this.allUsers)) return [];
      const search = this.mentionSearch.toLowerCase();
      if (!search) return this.allUsers.slice(0, 20);
      return this.allUsers
        .filter((user: any) => {
          const fullName = this.getUserFullName(user).toLowerCase();
          const email = (user.email || '').toLowerCase();
          return fullName.includes(search) || email.includes(search);
        })
        .slice(0, 20);
    },
  },

  async mounted() {
    if (this.docId) {
      await this.getAllUsers();
      this.fetchLogs();
    }
  },

  methods: {
    formatLogTime(dateString: string | Date | null | undefined): string {
      return useFormattedTimeAgo(dateString);
    },

    getUserFullName(user: any): string {
      return `${user.first_name || ''} ${user.last_name || ''}`.trim() || user.email || '';
    },

    getAvatarLetters(name: any): string {
      if (!name) return '-';
      const parts = name.split(' ').filter(Boolean);
      if (parts.length === 0) return '-';
      let initials = parts[0].charAt(0);
      if (parts.length >= 2) {
        initials += parts[parts.length - 1].charAt(0);
      }
      return initials;
    },

    resolveEmailToName(email: string): string {
      if (!this.allUsers || !Array.isArray(this.allUsers)) return email;
      const user = this.allUsers.find((u: any) => u.email === email);
      return user ? this.getUserFullName(user) : email;
    },

    // --- Log display ---

    renderMentions(text: string): string {
      if (!text) return '';
      const escaped = escapeHtml(text);
      // <<email>> becomes &lt;&lt;email&gt;&gt; after escaping
      return escaped.replace(
        /&lt;&lt;(.+?)&gt;&gt;/g,
        (_match: string, email: string) => {
          const name = this.resolveEmailToName(email);
          return `<span class="mention-highlight">@${escapeHtml(name)}</span>`;
        },
      );
    },

    // --- Contenteditable helpers ---

    focusEditor() {
      const editor = this.$refs.commentEditor as HTMLElement;
      if (editor) editor.focus();
    },

    getEditorElement(): HTMLElement | null {
      return (this.$refs.commentEditor as HTMLElement) || null;
    },

    getCursorOffset(): number {
      const editor = this.getEditorElement();
      if (!editor) return 0;
      const sel = window.getSelection();
      if (!sel || sel.rangeCount === 0) return 0;
      const range = sel.getRangeAt(0).cloneRange();
      range.selectNodeContents(editor);
      range.setEnd(sel.getRangeAt(0).startContainer, sel.getRangeAt(0).startOffset);
      return range.toString().length;
    },

    setCursorAtOffset(offset: number) {
      const editor = this.getEditorElement();
      if (!editor) return;
      const sel = window.getSelection();
      if (!sel) return;

      let currentOffset = 0;
      const walker = document.createTreeWalker(editor, NodeFilter.SHOW_TEXT, null);
      let node = walker.nextNode();
      while (node) {
        const nodeLen = (node.textContent || '').length;
        if (currentOffset + nodeLen >= offset) {
          const range = document.createRange();
          range.setStart(node, offset - currentOffset);
          range.collapse(true);
          sel.removeAllRanges();
          sel.addRange(range);
          return;
        }
        currentOffset += nodeLen;
        node = walker.nextNode();
      }
      // Fallback: cursor at end
      const range = document.createRange();
      range.selectNodeContents(editor);
      range.collapse(false);
      sel.removeAllRanges();
      sel.addRange(range);
    },

    // --- Editor highlight ---

    highlightMentionsInText(escapedText: string): string {
      const mentioned = this.mentionedUsers as MentionedUser[];
      if (mentioned.length === 0) return escapedText;

      let result = escapedText;
      for (const m of mentioned) {
        const nameInEscaped = escapeHtml(m.name);
        const pattern = new RegExp('@' + escapeRegex(nameInEscaped), 'g');
        result = result.replace(
          pattern,
          `<span class="mention-highlight">@${nameInEscaped}</span>`,
        );
      }
      return result;
    },

    highlightEditorContent() {
      const editor = this.getEditorElement();
      if (!editor) return;

      const cursorOffset = this.getCursorOffset();
      const plainText = editor.innerText || '';
      const highlighted = this.highlightMentionsInText(escapeHtml(plainText));

      if (editor.innerHTML !== highlighted) {
        editor.innerHTML = highlighted;
        this.setCursorAtOffset(cursorOffset);
      }
    },

    // --- Mention trigger ---

    isInsideCompletedMention(fullText: string, atIndex: number): boolean {
      for (const m of this.mentionedUsers as MentionedUser[]) {
        const mentionText = `@${m.name}`;
        if (fullText.substring(atIndex).startsWith(mentionText)) {
          return true;
        }
      }
      return false;
    },

    findMentionTrigger(textBeforeCursor: string): number {
      const fullText = this.new_message['text'] || textBeforeCursor;
      for (let i = textBeforeCursor.length - 1; i >= 0; i--) {
        const ch = textBeforeCursor[i];
        if (ch === '@' && (i === 0 || textBeforeCursor[i - 1] === ' ' || textBeforeCursor[i - 1] === '\n')) {
          if (this.isInsideCompletedMention(fullText, i)) return -1;
          return i;
        }
        if (ch === '\n') return -1;
      }
      return -1;
    },

    // --- Input handlers ---

    onEditorInput() {
      const editor = this.getEditorElement();
      if (!editor) return;

      const plainText = editor.innerText || '';
      this.new_message['text'] = plainText;
      this.new_message['error'] = false;

      this.highlightEditorContent();

      if (!plainText) {
        this.closeMentionList();
        return;
      }

      const cursorOffset = this.getCursorOffset();
      const textBeforeCursor = plainText.substring(0, cursorOffset);
      const atIndex = this.findMentionTrigger(textBeforeCursor);

      if (atIndex >= 0) {
        this.mentionStartIndex = atIndex;
        this.mentionSearch = textBeforeCursor.substring(atIndex + 1);
        this.mentionActiveIndex = 0;
        this.mentionMenuTarget = editor;
        this.showMentionList = true;
      } else {
        this.closeMentionList();
      }
    },

    scrollActiveIntoView() {
      this.$nextTick(() => {
        const listEl = (this.$refs.mentionDropdownList as any)?.$el;
        if (!listEl) return;
        const items = listEl.querySelectorAll('.q-item');
        const activeItem = items[this.mentionActiveIndex] as HTMLElement;
        if (activeItem) {
          activeItem.scrollIntoView({ block: 'nearest' });
        }
      });
    },

    onInputKeydown(e: KeyboardEvent) {
      if (!this.showMentionList) return;

      if (e.key === 'ArrowDown') {
        e.preventDefault();
        if (this.mentionActiveIndex < this.filteredUsers.length - 1) {
          this.mentionActiveIndex++;
          this.scrollActiveIntoView();
        }
      } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        if (this.mentionActiveIndex > 0) {
          this.mentionActiveIndex--;
          this.scrollActiveIntoView();
        }
      } else if (e.key === 'Enter' && this.filteredUsers.length > 0) {
        e.preventDefault();
        this.selectMention(this.filteredUsers[this.mentionActiveIndex]);
      } else if (e.key === 'Escape') {
        this.closeMentionList();
      }
    },

    selectMention(user: any) {
      const editor = this.getEditorElement();
      if (!editor) return;

      const fullName = this.getUserFullName(user);
      const displayText = `@${fullName}`;
      const plainText = editor.innerText || '';
      const cursorOffset = this.getCursorOffset();

      // Track mention first so highlight knows about it
      const alreadyMentioned = this.mentionedUsers.some(
        (m: MentionedUser) => m.user_id === user.id,
      );
      if (!alreadyMentioned) {
        this.mentionedUsers.push({
          name: fullName,
          user_id: user.id,
          email: user.email,
        });
      }

      const before = plainText.substring(0, this.mentionStartIndex);
      const after = plainText.substring(cursorOffset);
      const newText = before + displayText + ' ' + after;

      this.new_message['text'] = newText;
      editor.innerHTML = this.highlightMentionsInText(escapeHtml(newText));

      const newCursorPos = before.length + displayText.length + 1;
      this.setCursorAtOffset(newCursorPos);
      this.closeMentionList();
    },

    closeMentionList() {
      this.showMentionList = false;
      this.mentionSearch = '';
      this.mentionStartIndex = -1;
      this.mentionActiveIndex = 0;
    },

    // --- Data / API ---

    currentUserDisplayName(): string {
      const first = getUserDetailFromkey('first_name') || '';
      const last = getUserDetailFromkey('last_name') || '';
      const full = `${first} ${last}`.trim();
      return full || getUserDetailFromkey('username') || '';
    },

    decorateLog(row: any) {
      // Fill in display fields the POST response may omit (created_by_name,
      // created_on) so the new entry renders with avatar + author + timestamp.
      const created_by_name =
        row.created_by_name || this.currentUserDisplayName();
      const created_on = row.created_on || new Date().toISOString();
      return {
        ...row,
        created_by_name,
        created_on,
        avatar_letters: this.getAvatarLetters(created_by_name),
      };
    },

    // Tries to extract log rows from the update_document_log response so we can
    // skip a follow-up GET that may race against backend write visibility.
    // Handles a few likely shapes; returns null if the response is unrecognizable
    // and the caller should fall back to fetchLogs().
    extractLogsFromResponse(response: any): any[] | any | null {
      if (!response) return null;
      // Plain array (mirrors get_document_log shape — newest first)
      if (Array.isArray(response)) return response;
      // Wrapped: { data: [...] } or { logs: [...] }
      if (Array.isArray(response.data)) return response.data;
      if (Array.isArray(response.logs)) return response.logs;
      // Single newly-created entry
      const candidate = response.data || response.log || response;
      if (
        candidate &&
        typeof candidate === 'object' &&
        'action_description' in candidate &&
        'created_on' in candidate
      ) {
        return candidate;
      }
      return null;
    },

    applyLogsResponse(payload: any[] | any) {
      if (Array.isArray(payload)) {
        this.logs = payload.map((row: any) => this.decorateLog(row)).reverse();
      } else {
        // single new entry — append to existing list (oldest → newest order)
        this.logs.push(this.decorateLog(payload));
      }
      setTimeout(() => this.scrollToBottom(), 0);
    },

    async fetchLogs() {
      try {
        this.loading = true;
        const response: any = await documentDetailApiService.get_document_log(
          this.docId,
        );

        if (!response) return;
        if (response.success === false) throw response;

        this.applyLogsResponse(response);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    buildStorageText(text: string, mentions: MentionedUser[]): string {
      let result = text;
      for (const m of mentions) {
        result = result.split(`@${m.name}`).join(`<<${m.email}>>`);
      }
      return result;
    },

    async postComment() {
      try {
        if (!this.validateData()) return;

        this.loading = true;
        const text = this.new_message['text'];

        // Keep only mentions still present in text
        const activeMentions = (this.mentionedUsers as MentionedUser[]).filter(
          (m) => text.includes(`@${m.name}`),
        );

        const storageText = this.buildStorageText(text, activeMentions);

        const response: any =
          await documentDetailApiService.update_document_log(
            this.docId,
            storageText,
            this.doc_status,
            this.doc_status,
            activeMentions.length > 0 ? activeMentions : undefined,
          );

        if (response && response.success === false) throw response;

        this.new_message = { error: false, text: '' };
        this.mentionedUsers = [];
        const editor = this.getEditorElement();
        if (editor) editor.innerHTML = '';

        // Avoid the get-after-post race: if the POST response carries the new
        // log row(s), apply it directly. Only fall back to a fresh GET when the
        // response shape doesn't include log data.
        const fromResponse = this.extractLogsFromResponse(response);
        if (fromResponse !== null) {
          this.applyLogsResponse(fromResponse);
        } else {
          await this.fetchLogs();
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    validateData(): boolean {
      if (!this.new_message['text'] || this.new_message['text'].trim().length === 0) {
        this.new_message['error'] = true;
        return false;
      }
      return true;
    },

    scrollToBottom() {
      const scrollArea = document.querySelector('.activity-logs');
      if (scrollArea) {
        scrollArea.scrollTop = scrollArea.scrollHeight;
      }
    },
  },
});
</script>

<style lang="scss" scoped>
// Activity stream is a flex column so the messages list scrolls and the
// composer stays anchored at the bottom of the panel. We size the
// container absolutely against the parent SidebarPanel wrapper (which
// already has `relative-position`) — that gives us the exact panel
// bounds without depending on the global .left-scroll-area-height
// calc-based fallback, and prevents the dead whitespace that appears
// when the activity-logs is shorter than its parent panel.
.activity-logs {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  min-height: 0;
  // Neutralize the global .left-scroll-area-height
  height: auto;
}

.logs-scroll-area {
  flex: 1 1 auto;
  // `min-height: 0` is required so a flex child can actually shrink
  // below its content size and let `overflow-y` kick in.
  min-height: 0;
  overflow-y: auto;
}

.composer-area {
  flex: 0 0 auto;
  border-top: 1px solid var(--border, rgba(0, 0, 0, 0.08));
  background: var(--card, #fff);
}

.mention-input-wrapper {
  position: relative;
  width: 100%;
}

.comment-editor-container {
  position: relative;
  display: flex;
  align-items: flex-start;
  border: 1px solid rgba(0, 0, 0, 0.24);
  border-radius: 4px;
  padding: 8px 12px;
  transition: border-color 0.2s;
  background: var(--card, #fff);

  &:focus-within {
    border-color: var(--primary);
    border-width: 2px;
    padding: 7px 11px;
  }

  &.comment-editor-error {
    border-color: red;
  }
}

.comment-editor {
  flex: 1;
  min-height: 24px;
  max-height: 200px;
  overflow-y: auto;
  outline: none;
  font-size: 14px;
  line-height: 1.5;
  color: var(--foreground, #000);
  word-break: break-word;
  white-space: pre-wrap;
}

.comment-placeholder {
  position: absolute;
  top: 8px;
  left: 12px;
  color: var(--muted-foreground, rgba(0, 0, 0, 0.4));
  font-size: 14px;
  line-height: 1.5;
  cursor: text;
  pointer-events: auto;
}

.comment-editor-actions {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-left: 8px;
  flex-shrink: 0;
}

.mention-dropdown {
  max-height: 200px;
  overflow-y: auto;
  min-width: 220px;
  max-width: 320px;
}

.mention-avatar-section {
  min-width: 32px !important;
}

.mention-dropdown :deep(.q-item--active .q-item__label--caption) {
  color: rgba(255, 255, 255, 0.8);
}

:deep(.mention-highlight) {
  color: var(--primary);
  font-weight: 600;
  background-color: rgba(35, 136, 174, 0.1);
  border-radius: 3px;
  padding: 0 2px;
}
</style>
